function New-TestFixture {
 $parent=[IO.Path]::GetTempPath().TrimEnd('\');$root=Join-Path $parent ('ether-phase-a-store-'+[Guid]::NewGuid().ToString('N'));$p=Join-Path $root 'protected';$c=Join-Path $root 'control';[IO.Directory]::CreateDirectory($p)|Out-Null;[IO.Directory]::CreateDirectory($c)|Out-Null
 $f=@{root=$root;parent=$parent;protectedDir=$p;controlDir=$c;protectedFile=(Join-Path $p 'original.bin');newFile=(Join-Path $p 'committed.bin');deniedFile=(Join-Path $p 'rejected.bin');controlFile=(Join-Path $c 'original.bin');authorizedProbeFile=(Join-Path $p 'witness-authorized.bin');controlProbeFile=(Join-Path $c 'witness-permissive.bin');aclInspected=$true;initialDigest='wrong'}
 [IO.File]::WriteAllText($f.protectedFile,'synthetic');[IO.File]::WriteAllText($f.controlFile,'synthetic');return $f
}
function Run-TestCleanup($f,[string]$mode) {
 $binding=@{fixtureId=[IO.Path]::GetFileName($f.root);rootIdentity=$f.root;brokerSid='S-1-5-21-1';legacySid='S-1-5-21-2';source='INJECTED'}
 $backend=@{Setup={param($a,$e) $e.aclFixtureBinding=$binding;return $f}.GetNewClosure();Exists={param($p) [IO.File]::Exists($p)};Digest={param($p) 'different'};Cleanup={param($f) if($mode -ceq 'FAIL'){throw 'private failure'};if($mode -ceq 'REMOVE'){Remove-PhaseAFixture $f};if($mode -ceq 'PARTIAL'){[IO.File]::Delete($f.protectedFile)}}.GetNewClosure();CleanupVerified={param($f) -not [IO.Directory]::Exists($f.root)};CleanupObservation={param($f,$phase) Get-PhaseAFixtureCleanupObservation $f $phase 'INJECTED'}}
 $sink=@{};$null=Invoke-PhaseAStage3 @() @() $backend @{} $sink;return $sink.evidence
}
$f=New-TestFixture;try{$e=Run-TestCleanup $f 'REMOVE';if(-not $e.cleanupVerified -or -not $e.fixtureCleanup.attempted -or -not $e.fixtureCleanup.returned -or $e.fixtureCleanup.after.rootExists){throw 'successful cleanup not observed'};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $e 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'NOT_RUN' -or $e.fixtureCleanup.identityAssurance -cne 'PATH_ONLY'){throw 'path-only cleanup promoted to PASS'}}finally{if([IO.Directory]::Exists($f.root)){Remove-PhaseAFixture $f}}
$f=New-TestFixture;try{$e=Run-TestCleanup $f 'NOOP';if($e.cleanupVerified -or -not $e.fixtureCleanup.after.rootExists){throw 'false cleanup accepted'};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $e 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'FAIL'){throw 'survivor not retained'};$verify=New-PhaseAEvidenceVerifier $journal.ToArray() $v '1' $true $true 'SIMULATED_PASS' @() @{} $e;if(-not (& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v)){throw 'cleanup failure proof did not recheck'};$bad=$v.cases.fixtureCleanup.Clone();$bad.proof='0'*64;if(& $verify 'fixtureCleanup' $bad $v){throw 'forged cleanup proof accepted'};$original=$e.fixtureCleanup.after.unexpected;$e.fixtureCleanup.after.unexpected=1;if(& $verify 'fixtureCleanup' $v.cases.fixtureCleanup $v){throw 'stale cleanup proof accepted'};$e.fixtureCleanup.after.unexpected=$original;$relabeled=$e.Clone();$relabeled.fixtureCleanup=$e.fixtureCleanup.Clone();$relabeled.fixtureCleanup.before=$e.fixtureCleanup.before.Clone();$relabeled.fixtureCleanup.after=$e.fixtureCleanup.after.Clone();$relabeled.fixtureCleanup.before.source='LIVE';$relabeled.fixtureCleanup.after.source='LIVE';$relabeled.aclFixtureBinding=$e.aclFixtureBinding.Clone();$relabeled.aclFixtureBinding.source='LIVE';$live=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $live $relabeled 'LIVE_OBSERVED' $journal.ToArray();if($live.cases.fixtureCleanup.state -cne 'NOT_RUN'){throw 'relabeled injected cleanup accepted as live'}}finally{Remove-PhaseAFixture $f}
$f=New-TestFixture;try{$extra=Join-Path $f.protectedDir 'unexpected.bin';[IO.File]::WriteAllText($extra,'synthetic');$e=Run-TestCleanup $f 'REMOVE';if($e.cleanupVerified -or $e.fixtureCleanup.reason -cne 'CLEANUP_FAILED' -or $e.fixtureCleanup.after.unexpected -ne 1){throw 'unexpected survivor not retained'};[IO.File]::Delete($extra)}finally{if([IO.Directory]::Exists($f.root)){Remove-PhaseAFixture $f}}
foreach($mode in @('FAIL','PARTIAL')){$f=New-TestFixture;try{$e=Run-TestCleanup $f $mode;$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $e 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'FAIL' -or $v.cases.fixtureCleanup.reason -cne 'CLEANUP_UNCONFIRMED' -or $e.cleanupVerified){throw "cleanup failure lost: $mode"};if($mode -ceq 'FAIL' -and $e.fixtureCleanup.reason -cne 'CLEANUP_FAILED'){throw 'cleanup exception not recorded'}}finally{Remove-PhaseAFixture $f}}
$f=New-TestFixture;try{$e=Run-TestCleanup $f 'REMOVE';foreach($case in @('fixture','phase','missing','source','forged','observation')){$bad=$e.Clone();$bad.fixtureCleanup=$e.fixtureCleanup.Clone();$bad.fixtureCleanup.after=$e.fixtureCleanup.after.Clone();$bad.aclFixtureBinding=$e.aclFixtureBinding.Clone();switch($case){'fixture' {$bad.aclFixtureBinding.fixtureId='ether-phase-a-store-'+('b'*32)} 'phase' {$bad.fixtureCleanup.after.phase='BEFORE'} 'missing' {$bad.fixtureCleanup.after=$null} 'source' {$bad.fixtureCleanup.after.source='LIVE'} 'forged' {$bad.fixtureCleanup.after.existing=@('protected/original.bin')} 'observation' {$bad.fixtureCleanup.after.status='UNVERIFIED'}};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $bad 'SIMULATED_PASS' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'NOT_RUN'){throw "invalid cleanup evidence accepted: $case"}};$v=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v $e 'LIVE_OBSERVED' $journal.ToArray();if($v.cases.fixtureCleanup.state -cne 'NOT_RUN'){throw 'injected cleanup accepted as live'}}finally{if([IO.Directory]::Exists($f.root)){Remove-PhaseAFixture $f}}
$f=New-TestFixture;try{$f.controlDir=[IO.Path]::GetTempPath();$obs=Get-PhaseAFixtureCleanupObservation $f 'BEFORE' 'INJECTED';if($obs.status -cne 'UNVERIFIED'){throw 'outside path accepted'};$f.controlDir=Join-Path $f.root 'control'}finally{Remove-PhaseAFixture $f}
$f=New-TestFixture;try{function Get-Item {param([string]$LiteralPath,[switch]$Force) if($LiteralPath -ceq $f.root){return [pscustomobject]@{Attributes=[IO.FileAttributes]::ReparsePoint}};Microsoft.PowerShell.Management\Get-Item -LiteralPath $LiteralPath -Force:$Force -ErrorAction Stop};$obs=Get-PhaseAFixtureCleanupObservation $f 'BEFORE' 'INJECTED';if($obs.status -cne 'UNVERIFIED' -or $obs.reason -cne 'REPARSE_REJECTED'){throw 'reparse observation accepted'}}finally{Remove-Item Function:\Get-Item -ErrorAction SilentlyContinue;Remove-PhaseAFixture $f}
. "$PSScriptRoot/PhaseA.InventoryBridge.Tests.ps1"
$fakeState.created=$false;$fakeState.mutated=$false;$script:sequence=0;$script:cleanupEvents=New-Object 'System.Collections.Generic.List[string]';$failingFixture.CleanupObservation={param($f,$phase) throw 'must not observe unconfirmed child'};$j=New-Object 'System.Collections.Generic.List[object]';$wrapped=New-PhaseAActorJournalBackend $failingActors $j;$sink3=@{};$status=Invoke-PhaseAStages $true $true $accountBackend $wrapped $true $failingFixture $sink3
if($status -cne 'ACCOUNT_CLEANUP_FAILED' -or $script:cleanupEvents.Count -ne 0 -or $sink3.evidence.fixtureCleanup.attempted -or $sink3.evidence.fixtureCleanup.authorized -or $sink3.evidence.fixtureCleanup.reason -cne 'CHILD_UNCONFIRMED'){throw 'unconfirmed cleanup gate failed'};$prior=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $prior $sink3.evidence 'SIMULATED_PASS' $j.ToArray();if($prior.cases.protectedInventory.state -cne 'FAIL' -or $prior.cases.fixtureCleanup.state -cne 'NOT_RUN'){throw 'earlier violation lost or blocked cleanup accepted'}
$fakeState.created=$false;$fakeState.mutated=$false;$script:sequence=0;$failingFixture.Cleanup={param($f) throw 'synthetic cleanup error'};$failingFixture.CleanupObservation={param($f,$phase) @{status='OBSERVED';reason='NONE';phase=$phase;source='INJECTED';fixtureId=[IO.Path]::GetFileName($f.root);rootIdentity=$f.root;parentIdentity=$f.parent;identityAssurance='PATH_ONLY';rootExists=$true;existing=@('.');unexpected=0}}
$nonfatalActors=@{Run={param($a,$t,$op,$target) $r=& $originalRun $a $t $op $target;if($a.role -ceq 'legacy' -and $op -ceq 'Read' -and $target -ceq $fakeFixture.protectedFile){$fakeState.mutated=$true};return $r}.GetNewClosure()};$j2=New-Object 'System.Collections.Generic.List[object]';$wrapped2=New-PhaseAActorJournalBackend $nonfatalActors $j2;$sink4=@{};$null=Invoke-PhaseAStages $true $true $accountBackend $wrapped2 $true $failingFixture $sink4;$v4=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $v4 $sink4.evidence 'SIMULATED_PASS' $j2.ToArray();if($sink4.evidence.fixtureCleanup.reason -cne 'CLEANUP_FAILED' -or $v4.cases.protectedInventory.state -cne 'FAIL'){throw 'cleanup failure discarded earlier inventory violation'}
Write-Output 'PASS fixture cleanup current-identity and injected controls'
